using UnityEngine;

// Every professor picture is laid out by its face (PortraitFaces, generated by Tools/generate_portrait_faces.py):
// the same face size and eye line whatever the framing of the source (full body, bust or close-up), and the source's
// real shape, because Unity imports these pictures stretched to power-of-two sizes. Pictures missing from the table
// fall back to the older per-professor framing in DrawScene and the menus.
public partial class GameController
{
    // On stage the face is this tall, centred on this line (canvas px): level with the player's head in a duo.
    const float StageFaceHeight = 140f, StageFaceY = 345f;
    const float StageFadeHeight = 60f;   // a close-up's cut-off edge dissolves over this many px instead of ending in a line

    static bool TryFace(Texture2D texture, out PortraitFaces.Entry face)
    {
        face = default;
        return texture != null && PortraitFaces.Face.TryGetValue(texture.name, out face);
    }

    /// <summary>Where the whole picture goes so its face is faceHeight tall and centred on faceCentre.</summary>
    static Rect FaceLayout(PortraitFaces.Entry face, float faceHeight, Vector2 faceCentre)
    {
        float height = faceHeight / face.Size;
        float width = height * face.Aspect;
        return new Rect(faceCentre.x - face.X * width, faceCentre.y - face.Y * height, width, height);
    }

    /// <summary>Draws the picture laid out in rect down to the figure's lowest pixel (or clipBottom). When the figure
    /// ends above clipBottom its last fade px dissolve, so a cropped torso never ends in a hard line.</summary>
    static void DrawFigure(Texture2D texture, PortraitFaces.Entry face, Rect rect, float clipBottom, float fade, Color tint)
    {
        float bottom = rect.y + face.Bottom * rect.height;
        bool cut = bottom < clipBottom;
        float solid = cut ? bottom - fade : clipBottom;
        GUI.color = tint;
        DrawRows(texture, rect, rect.y, solid);
        if (cut)
        {
            const int strips = 8;
            float step = fade / strips;
            for (int i = 0; i < strips; i++)
            {
                GUI.color = new Color(tint.r, tint.g, tint.b, tint.a * (1f - (i + .5f) / strips));
                DrawRows(texture, rect, solid + i * step, solid + (i + 1) * step);
            }
        }
        GUI.color = Color.white;
    }

    /// <summary>Draws the horizontal band top…bottom of a picture laid out in rect.</summary>
    static void DrawRows(Texture2D texture, Rect rect, float top, float bottom)
    {
        top = Mathf.Max(top, rect.y);
        bottom = Mathf.Min(bottom, rect.yMax);
        if (bottom <= top) return;
        float v0 = (top - rect.y) / rect.height, v1 = (bottom - rect.y) / rect.height;   // from the top
        GUI.DrawTextureWithTexCoords(new Rect(rect.x, top, rect.width, bottom - top), texture, new Rect(0, 1f - v1, 1, v1 - v0));
    }

    /// <summary>The professor in the story scene: centred, or across from the player in a duo. Keeps the breathing,
    /// entrance slide and reaction hop of PortraitRect. False when the picture isn't in the table.</summary>
    bool DrawStageProfessor(Texture2D texture, Color tint, bool duo)
    {
        if (!TryFace(texture, out PortraitFaces.Entry face)) return false;
        Matrix4x4 saved = GUI.matrix;
        Rect motion = PortraitRect();   // the full screen, moved and scaled by the current animation
        GUI.matrix = Matrix4x4.Translate(new Vector3(motion.x, motion.y, 0))
            * Matrix4x4.Scale(new Vector3(motion.width / Screen.width, motion.height / Screen.height, 1)) * Canvas;
        float centreX = duo ? 1280f - DuoPlayerX : 640f;
        Rect rect = FaceLayout(face, StageFaceHeight, new Vector2(centreX, StageFaceY));
        DrawFigure(texture, face, rect, NovelUI.Window.yMax, StageFadeHeight, tint);
        GUI.matrix = saved;
        return true;
    }

    /// <summary>A portrait inside a menu frame (card, save slot, gallery), clipped to it. faceShare is the face's
    /// height as a share of the frame's, faceY where its centre sits (share from the top). Draws on Repaint only.</summary>
    static bool DrawPortraitInFrame(Rect frame, Texture2D texture, float faceShare, float faceY)
    {
        if (!TryFace(texture, out PortraitFaces.Entry face)) return false;
        if (!NovelUI.Repaint) return true;
        GUI.BeginGroup(frame);
        Rect rect = FaceLayout(face, frame.height * faceShare, new Vector2(frame.width / 2, frame.height * faceY));
        DrawFigure(texture, face, rect, frame.height, frame.height * .14f, GUI.color);
        GUI.EndGroup();
        return true;
    }
}
